/// ustar headers are 512 bytes; payload is padded to that size.
pub struct Row {
    pub name: String,
    pub hdr: u64,
    pub size: u64,
    pub body: u64,
    pub flag: u8,
}

fn oct_u64(buf: &[u8]) -> Result<u64, i32> {
    let mut n = 0u64;
    let mut seen = false;
    for &b in buf {
        match b {
            0 | b' ' if !seen => continue,
            0 | b' ' => break,
            b'0'..=b'7' => {
                seen = true;
                n = n.checked_mul(8).and_then(|v| v.checked_add(u64::from(b-b'0'))).ok_or(1)?;
            }
            _ => return Err(1),
        }
    }
    if seen { Ok(n) } else { Err(1) }
}

pub fn scan(path: &str) -> Result<Vec<Row>, i32> {
    let raw = std::fs::read(path).map_err(|_| 1)?;
    if raw.len() < 1024 || raw.len() % 512 != 0 { return Err(1); }
    let mut rows = Vec::new();
    let mut off = 0usize;
    let mut ended = false;
    while off + 512 <= raw.len() {
        let blk = &raw[off..off+512];
        if blk.iter().all(|&b| b == 0) {
            if off + 1024 > raw.len() || !raw[off+512..off+1024].iter().all(|&b| b == 0) {
                return Err(1);
            }
            ended = true;
            break;
        }
        if &blk[257..262] != b"ustar" { return Err(1); }
        let nlen = blk[0..100].iter().position(|&b| b == 0).unwrap_or(100);
        if nlen == 0 { return Err(1); }
        let name = std::str::from_utf8(&blk[0..nlen]).map_err(|_| 1)?.to_string();
        let size = oct_u64(&blk[124..136])?;
        let padded = size.checked_add(511).ok_or(1)? / 512 * 512;
        let next = (off as u64).checked_add(512).and_then(|v| v.checked_add(padded)).ok_or(1)?;
        if next > raw.len() as u64 { return Err(1); }
        rows.push(Row { name, hdr: off as u64, size, body: (off+512) as u64, flag: blk[156] });
        off = next as usize;
    }
    if rows.is_empty() || !ended { return Err(1); }
    Ok(rows)
}

pub fn load_body(path: &str, row: &Row) -> Result<Vec<u8>, i32> {
    let raw = std::fs::read(path).map_err(|_| 1)?;
    let s = row.body as usize;
    let e = s.checked_add(row.size as usize).ok_or(1)?;
    if e > raw.len() { return Err(1); }
    Ok(raw[s..e].to_vec())
}
